for f in ['source.json','policy.json','coordination.json','reference-targets.json']:
 d=json.load(open(f)); print('\\n',f, type(d).__name__)
 if isinstance(d,dict):
  for k,v in d.items(): print(k, type(v).__name__, len(v) if isinstance(v,(list,dict,str)) else v)
 elif isinstance(d,list):
  for v in d: print({k:(len(x) if k in ['source_xml','source_notes_xml'] and isinstance(x,str) else x) for k,x in v.items() if k not in ['sru_context','source_companions']})
PY"

